#include <bits/stdc++.h>
using namespace std;

int n;
vector<int> perm;

void doOp(int x, int y, vector<pair<int,int>>& ops) {
    ops.push_back({x, y});
    vector<int> np(n);
    for (int i = 0; i < y; i++) np[i] = perm[n - y + i];
    for (int i = x; i < n - y; i++) np[y + i - x] = perm[i];
    for (int i = 0; i < x; i++) np[n - x + i] = perm[i];
    perm = np;
}

int main(){
    scanf("%d", &n);
    perm.resize(n);
    for (int i = 0; i < n; i++) scanf("%d", &perm[i]);

    vector<pair<int,int>> ops;

    for (int k = 0; k < n; k++) {
        int pos = -1;
        for (int i = k; i < n; i++) if (perm[i] == k + 1) { pos = i; break; }
        if (pos == k) continue;

        // We need to move element from pos to k.
        // pos > k always (since positions 0..k-1 are already correct)
        // Try all valid (x,y) pairs to achieve this in one op
        bool done = false;
        for (int x = 1; x < n && !done; x++) {
            for (int y = 1; x + y < n && !done; y++) {
                int newpos;
                if (pos >= n - y) newpos = pos - (n - y);
                else if (pos >= x) newpos = y + pos - x;
                else newpos = n - x + pos;

                if (newpos == k) {
                    // Check positions 0..k-1 are unchanged
                    bool ok = true;
                    for (int i = 0; i < k && ok; i++) {
                        int ni;
                        if (i >= n - y) ni = i - (n - y);
                        else if (i >= x) ni = y + i - x;
                        else ni = n - x + i;
                        if (ni != i) ok = false;
                    }
                    if (ok) { doOp(x, y, ops); done = true; }
                }
            }
        }
        if (done) continue;

        // Fallback: two operations
        // First move pos to position n-1: need x=1, y such that pos maps to n-1
        // pos in [1, n-y-1] -> y+pos-1 = n-1 -> y = n-pos, then x+y = 1+n-pos < n iff pos>1
        if (pos > 1) {
            doOp(1, n - pos, ops);
            pos = n - 1;
        }
        // Now pos might be n-1, move to k
        // pos=n-1, need n-1 >= n-y -> y>=1, newpos=n-1-(n-y)=y-1=k -> y=k+1, x>=1, x+k+1<n -> x<=n-k-2
        if (pos == n - 1 && k + 2 <= n) {
            doOp(max(1, k + 1), k + 1, ops);
        }
    }

    printf("%d\n", (int)ops.size());
    for (auto& [x, y] : ops) printf("%d %d\n", x, y);
}
